const SETTINGS_IA_STYLE = String.raw`
.vr-settings-ia-root{width:100%;min-width:0}.vr-ia-shell{display:grid;grid-template-columns:158px minmax(0,1fr);gap:18px;align-items:start}.vr-ia-nav{position:sticky;top:12px;display:flex;flex-direction:column;gap:4px;padding:4px}.vr-ia-nav-item{border:0;background:transparent;color:inherit;text-align:left;padding:9px 11px;border-radius:9px;font:inherit;cursor:pointer;opacity:.72}.vr-ia-nav-active{background:color-mix(in srgb,currentColor 10%,transparent);font-weight:650;opacity:1}.vr-ia-main{min-width:0}.vr-ia-section-head{margin:0 0 12px}.vr-ia-title{margin:0 0 4px;font-size:18px}.vr-ia-card{margin-bottom:12px}.vr-ia-toggle-row,.vr-ia-backend-head,.vr-ia-diag-row{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:10px 0}.vr-ia-diag-row+.vr-ia-diag-row,.vr-ia-toggle-row+.vr-ia-toggle-row{border-top:1px solid color-mix(in srgb,currentColor 10%,transparent)}.vr-ia-grow{min-width:0;flex:1}.vr-ia-status strong{font-size:15px}.vr-ia-chain-summary{margin:8px 0 0;font-size:12px;opacity:.74}.vr-ia-subtitle{margin:12px 0 8px;font-size:14px}.vr-ia-subgrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.vr-ia-textarea{min-height:88px;resize:vertical}.vr-ia-field-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:5px}.vr-ia-badges{display:flex;align-items:center;gap:6px}.vr-ia-badge{font-size:10px;opacity:.65}.vr-ia-readonly{margin:0 0 10px;padding:8px 10px;border-radius:9px;background:color-mix(in srgb,currentColor 7%,transparent);font-size:12px}.vr-ia-savebar{position:sticky;bottom:10px;z-index:5;display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:14px;padding:10px 12px;border:1px solid color-mix(in srgb,currentColor 14%,transparent);border-radius:11px;background:color-mix(in srgb,Canvas 94%,transparent);backdrop-filter:blur(10px)}.vr-ia-save-actions,.vr-ia-actions{display:flex;gap:8px;flex-wrap:wrap}.vr-ia-toast{margin-top:10px;font-size:12px;opacity:.75}.vr-ia-dev{margin-top:12px}.vr-ia-manual{display:flex;flex-direction:column;gap:7px;margin-top:10px}.vr-ia-code{display:block;overflow:auto;white-space:pre;padding:8px 10px;border:1px solid color-mix(in srgb,currentColor 12%,transparent);border-radius:8px;font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;font-size:11px}.vr-settings-ia-root .vr-chain-row{align-items:center}.vr-settings-ia-root .vr-field{margin-bottom:10px}
@media (max-width:760px){.vr-ia-shell{grid-template-columns:1fr;gap:10px}.vr-ia-nav{position:static;flex-direction:row;overflow:auto;padding:0 0 4px}.vr-ia-nav-item{white-space:nowrap}.vr-ia-subgrid{grid-template-columns:1fr}.vr-ia-savebar{bottom:6px}}
`

export function injectSettingsIaClientPrelude(html) {
  if (typeof html !== 'string' || html.includes(CLIENT_MARK)) return html
  const script = `<style ${CLIENT_MARK}>${SETTINGS_IA_STYLE}</style><script ${CLIENT_MARK}>${SETTINGS_IA_CLIENT_PRELUDE.replace(/<\/script/gi, '<\\/script')}</script>`
  const closeHead = html.indexOf('</head>')
  return closeHead === -1 ? `${html}${script}` : `${html.slice(0, closeHead)}${script}${html.slice(closeHead)}`
}

export function installSettingsIaClientPrelude(ctx) {
  ctx?.inject?.(['webServer'], (webCtx) => {
    webCtx.effect(
      () => webCtx.webServer.tapIndex(injectSettingsIaClientPrelude),
      'vision-router: settings information architecture client prelude',
    )
  })
}
